//! Server-wide settings stored in the `settings` table.

use crate::{db::Pool, error::Result};

/// The installation's instance id (for example `ocb4c1e2f3a9`), the suffix of `oc:id`.
///
/// Generated by migration 0002, so it exists in every migrated database.
pub async fn instance_id(pool: &Pool) -> Result<String> {
    Ok(
        sqlx::query_scalar("SELECT value FROM settings WHERE name = 'instance_id'")
            .fetch_one(pool)
            .await?,
    )
}
